            cursor: pointer;
            box-shadow: 0 8px 20px rgba(23, 105, 224, .25);
            transition: .25s ease;
        }

        .pay-button:hover:not(:disabled) {
            transform: translateY(-2px);
            box-shadow: 0 12px 25px rgba(23, 105, 224, .32);
